use serde_json::{json,Value};
use std::{cell::RefCell,collections::HashMap,sync::{Arc,Mutex,OnceLock,atomic::{AtomicBool,AtomicUsize,Ordering}},time::{Duration,Instant}};
struct Stream { cancelled:Arc<AtomicBool>, data:Mutex<Data>, cookie:Option<String> }
static EVENT_BYTES:AtomicUsize=AtomicUsize::new(0);
impl Drop for Stream {fn drop(&mut self){let d=self.data.get_mut().unwrap_or_else(|e|e.into_inner());EVENT_BYTES.fetch_sub(d.bytes,Ordering::Relaxed);}}
struct Data { events:Vec<Value>, next:u64, done:bool, started:bool, committed:bool, bytes:usize, updated:Instant }
type Key=(String,String);
fn registry()->&'static Mutex<HashMap<Key,Arc<Stream>>>{static R:OnceLock<Mutex<HashMap<Key,Arc<Stream>>>>=OnceLock::new();R.get_or_init(||Mutex::new(HashMap::new()))}
fn valid_id(id:&str)->bool{uuid::Uuid::parse_str(id).is_ok()}
fn valid_wid(wid:&str)->bool{wid=="default" || (wid.len()==32&&wid.bytes().all(|c|c.is_ascii_hexdigit()))}
fn make(cookie:Option<String>,cancelled:bool)->Arc<Stream>{Arc::new(Stream{cancelled:Arc::new(AtomicBool::new(cancelled)),cookie,data:Mutex::new(Data{events:vec![],next:1,done:false,started:false,committed:false,bytes:0,updated:Instant::now()})})}
fn cleanup(map:&mut HashMap<Key,Arc<Stream>>){map.retain(|_,s|{let keep=s.data.lock().map(|d|d.updated.elapsed()<Duration::from_secs(600)).unwrap_or(false);if !keep{s.cancelled.store(true,Ordering::Release)}keep});}
fn room(map:&mut HashMap<Key,Arc<Stream>>,key:&Key)->bool{if map.len()<256||map.contains_key(key){return true}let oldest=map.iter().filter_map(|(k,s)|{let d=s.data.lock().ok()?;if d.done&&d.updated.elapsed()>Duration::from_secs(10){Some((k.clone(),d.updated))}else{None}}).min_by_key(|(_,time)|*time).map(|(key,_)|key);if let Some(key)=oldest{map.remove(&key);true}else{false}}
struct Running(Arc<Stream>);
impl Drop for Running {fn drop(&mut self){if let Ok(mut d)=self.0.data.lock(){d.done=true;d.updated=Instant::now();}}}
thread_local!{static PENDING:RefCell<Option<(String,Option<String>)>>=const{RefCell::new(None)};static CURRENT:RefCell<Option<Running>>=const{RefCell::new(None)};}
pub fn prepare(wid:&str,cookie:Option<String>){PENDING.with(|p|*p.borrow_mut()=Some((wid.to_owned(),cookie)));}
fn register(value:&Value)->Result<(),()>{let Some(request_id)=value.get("request_id") else{return Ok(())};let id=request_id.as_str().filter(|id|valid_id(id)).ok_or(())?;let pending=PENDING.with(|p|p.borrow_mut().take()).ok_or(())?;let mut map=registry().lock().map_err(|_|())?;cleanup(&mut map);let key=(pending.0,id.to_owned());if !room(&mut map,&key){return Err(())}let stream=map.entry(key).or_insert_with(||make(pending.1.clone(),false)).clone();if stream.cookie!=pending.1{return Err(())}{let mut data=stream.data.lock().map_err(|_|())?;if data.started{return Err(())}data.started=true;data.updated=Instant::now();}let cancelled=stream.cancelled.clone();let target=stream.clone();atlas_llama_probe::set_stream_sink(Arc::new(move |text|{if text.is_empty(){push_to(&target,json!({"type":"reset"}));}else{push_to(&target,json!({"type":"token","text":text}));}}),cancelled);CURRENT.with(|c|*c.borrow_mut()=Some(Running(stream)));Ok(())}
pub fn register_if_prepared(value:&Value)->Result<(),()>{if PENDING.with(|p|p.borrow().is_some()){register(value)?}Ok(())}
fn push_to(stream:&Stream,mut value:Value){if stream.cancelled.load(Ordering::Acquire){return}if let Ok(mut data)=stream.data.lock(){if data.done||stream.cancelled.load(Ordering::Acquire){return}let size=serde_json::to_vec(&value).map(|v|v.len().saturating_add(32)).unwrap_or(usize::MAX);if data.events.len()>=8192||size>8*1024*1024usize||data.bytes.saturating_add(size)>8*1024*1024||EVENT_BYTES.fetch_update(Ordering::AcqRel,Ordering::Relaxed,|n|n.checked_add(size).filter(|v|*v<=64*1024*1024)).is_err(){stream.cancelled.store(true,Ordering::Release);data.done=true;data.updated=Instant::now();return}data.bytes+=size;let seq=data.next;data.next+=1;value["seq"]=json!(seq);data.events.push(value);data.updated=Instant::now();}}
pub fn results(value:&[Value]){CURRENT.with(|c|if let Some(s)=c.borrow().as_ref(){push_to(&s.0,json!({"type":"results","results":value}));})}
pub fn progress(stage:&str,text:&str){CURRENT.with(|c|if let Some(s)=c.borrow().as_ref(){push_to(&s.0,json!({"type":"progress","stage":stage,"text":text}));})}
pub fn commit<T>(f:impl FnOnce()->T)->Result<T,()> {CURRENT.with(|c|{let borrowed=c.borrow();let Some(running)=borrowed.as_ref() else{return Ok(f())};let s=&running.0;let mut d=s.data.lock().map_err(|_|())?;if s.cancelled.load(Ordering::Acquire){return Err(())}d.committed=true;Ok(f())})}
pub fn cancelled()->bool{CURRENT.with(|c|c.borrow().as_ref().is_some_and(|s|s.0.cancelled.load(Ordering::Acquire)))}
pub fn finish(status:u16,value:&Value){CURRENT.with(|c|if let Some(running)=c.borrow_mut().take(){let s=&running.0;if !s.cancelled.load(Ordering::Acquire){push_to(s,if status<300 {let mut v=value.clone();v["type"]=json!("done");v}else{json!({"type":"error","error":value["error"].as_str().unwrap_or("Не удалось выполнить поиск")})});}if let Ok(mut d)=s.data.lock(){d.done=true;d.updated=Instant::now();}});PENDING.with(|p|*p.borrow_mut()=None);atlas_llama_probe::clear_stream_sink();}
pub fn events(wid:&str,id:&str,cookie:Option<String>,after:u64)->Option<Value>{if !valid_wid(wid)||!valid_id(id){return None}let stream={let mut map=registry().lock().ok()?;cleanup(&mut map);map.get(&(wid.to_owned(),id.to_owned()))?.clone()};if stream.cookie!=cookie{return None}let data=stream.data.lock().ok()?;Some(json!({"events":data.events.iter().filter(|v|v["seq"].as_u64().is_some_and(|n|n>after)).collect::<Vec<_>>(),"done":data.done}))}
pub fn drop_workspace(wid:&str){if let Ok(mut map)=registry().lock(){map.retain(|(w,_),s|{if w!=wid{return true}if let Ok(mut d)=s.data.lock(){s.cancelled.store(true,Ordering::Release);d.events.clear();EVENT_BYTES.fetch_sub(d.bytes,Ordering::Relaxed);d.bytes=0;d.done=true;}else{s.cancelled.store(true,Ordering::Release);}false});}}
pub fn cancel(wid:&str,id:&str,cookie:Option<String>)->bool{if !valid_wid(wid)||!valid_id(id){return false}let mut map=match registry().lock(){Ok(m)=>m,Err(_)=>return false};cleanup(&mut map);let key=(wid.to_owned(),id.to_owned());if !room(&mut map,&key){return false}let stream=map.entry(key).or_insert_with(||make(cookie.clone(),true)).clone();if stream.cookie!=cookie{return false}let mut data=match stream.data.lock(){Ok(v)=>v,Err(_)=>return false};if data.committed||data.done{return false}stream.cancelled.store(true,Ordering::Release);data.updated=Instant::now();true}
#[cfg(test)] mod tests {
 use super::*;
 static TEST_GUARD:Mutex<()>=Mutex::new(());
 #[test] fn cancellation_before_registration_and_workspace_isolation(){let _test=TEST_GUARD.lock().unwrap();let id=uuid::Uuid::new_v4().to_string();assert!(cancel("default",&id,None));prepare("default",None);register(&json!({"request_id":id})).unwrap();assert!(cancelled());finish(499,&json!({}));assert!(events("default",&id,None,0).unwrap()["done"]==true);assert!(events("11111111111111111111111111111111",&id,None,0).is_none());}
 #[test] fn event_cursor_and_session_cookie(){let _test=TEST_GUARD.lock().unwrap();let id=uuid::Uuid::new_v4().to_string();prepare("default",Some("session1".into()));register(&json!({"request_id":id})).unwrap();results(&[json!({"text":"x"})]);results(&[json!({"text":"y"})]);let response=events("default",&id,Some("session1".into()),1).unwrap();assert_eq!(response["events"].as_array().unwrap().len(),1);assert!(events("default",&id,Some("session2".into()),0).is_none());finish(200,&json!({"answer":"ok"}));assert!(events("default",&id,Some("session1".into()),0).unwrap()["done"]==true);}
 #[test] fn cancelled_stream_never_accepts_a_waiting_push(){let _test=TEST_GUARD.lock().unwrap();let s=make(None,false);let lock=s.data.lock().unwrap();let other=s.clone();let t=std::thread::spawn(move||push_to(&other,json!({"type":"token","text":"late"})));std::thread::sleep(Duration::from_millis(25));s.cancelled.store(true,Ordering::Release);drop(lock);t.join().unwrap();assert!(s.data.lock().unwrap().events.is_empty());}
 #[test] fn event_memory_is_released_after_poison(){let _test=TEST_GUARD.lock().unwrap();let baseline=EVENT_BYTES.load(Ordering::Relaxed);let s=make(None,false);push_to(&s,json!({"type":"token","text":"hello"}));assert!(EVENT_BYTES.load(Ordering::Relaxed)>baseline);let other=s.clone();let _=std::thread::spawn(move||{let _lock=other.data.lock().unwrap();panic!("poison test")}).join();drop(s);assert_eq!(EVENT_BYTES.load(Ordering::Relaxed),baseline);}
 #[test] fn concurrent_stream_events_release_budget(){let _test=TEST_GUARD.lock().unwrap();let baseline=EVENT_BYTES.load(Ordering::Relaxed);let s=make(None,false);let mut threads=vec![];for _ in 0..4{let s=s.clone();threads.push(std::thread::spawn(move||{for _ in 0..100{push_to(&s,json!({"type":"token","text":"x"}));}}));}for t in threads{t.join().unwrap();}assert_eq!(s.data.lock().unwrap().events.len(),400);drop(s);assert_eq!(EVENT_BYTES.load(Ordering::Relaxed),baseline);}

}
